-- ----------sql2------------
-- 3
SELECT COUNT(*) FROM ( SELECT T1.NATIONALITY FROM DRIVERS AS T1 ORDER BY JULIANDAY(T1.DOB) DESC LIMIT 3) AS T3 WHERE T3.NATIONALITY = 'DUTCH';

